"""无外部依赖的调试页面；纯文本渲染，不解释模型返回的 HTML。"""

PAGE = r'''<!doctype html>
<html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>QQ Bot · 对话调试</title><style nonce="__NONCE__">
:root{font:15px/1.6 system-ui,"Microsoft YaHei",sans-serif;color:#24303d;background:#f3f5f8;color-scheme:light}
*{box-sizing:border-box}body{margin:0}main{max-width:1480px;height:100dvh;margin:auto;display:grid;grid-template-columns:200px minmax(0,1fr);gap:24px;padding:12px 20px}
.sidebar{min-height:0;overflow-y:auto;border-right:1px solid #dfe5ed;padding:8px 18px 8px 0}.sidebar h2{font-size:12px;font-weight:600;color:#7b8797;margin:0 0 8px}.sidebar h2:not(:first-child){margin-top:22px}.chat{min-width:0;min-height:0;display:flex;flex-direction:column}
header{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap;padding:4px 0 10px;border-bottom:1px solid #e1e6ed}h1{font-size:20px;margin:0}#status{font-size:12px;color:#65758a}
.note{font-size:12px;color:#65758a;margin:8px 0}.note strong{color:#a25a26}.guide{font-size:12px;color:#65758a;margin-top:22px}.guide summary{cursor:pointer}#messages{flex:1;overflow-y:auto;padding:20px 0 8px;min-height:0;overscroll-behavior:contain}
.row{display:flex;flex-direction:column;align-items:flex-start;margin:0 0 18px}.row.user{align-items:flex-end}.label{font-size:12px;color:#7b8797;margin:0 6px 4px}
.bubble{max-width:88%;white-space:pre-wrap;overflow-wrap:anywhere;padding:12px 16px;border-radius:16px;background:white;border:1px solid #e4e9ef}
.generated{display:block;max-width:100%;max-height:60dvh;border-radius:10px;margin-top:8px}.user .bubble{background:#e4edff;border-color:#d9e4fa}.system .bubble{color:#895d30;background:#fff8ee}.toolbar{display:flex;flex-direction:column;gap:8px}.toolbar button{text-align:left;width:100%}
button{font:inherit;border:1px solid #d5dce6;background:white;color:#3d536d;border-radius:9px;padding:6px 12px;cursor:pointer}button:hover{background:#eaf0f9}button:disabled{opacity:.5;cursor:wait}
form{display:flex;gap:10px;align-items:flex-end;padding-top:8px}textarea{resize:vertical;height:60px;min-height:56px;max-height:180px;flex:1;min-width:0;border:1px solid #d5dce6;border-radius:12px;padding:10px 12px;font:inherit;background:white;color:inherit}
textarea:focus{outline:2px solid #95b6ef;border-color:transparent}#send{background:#426bd5;color:white;border:0;height:44px;padding:0 20px}#progress{min-height:24px;font-size:12px;color:#65758a;margin-top:6px}audio{max-width:100%;display:block;margin-top:8px}
#attachments{display:flex;gap:8px;flex-direction:column;margin:10px 0}.attachment{display:flex;align-items:center;gap:6px;min-width:0;background:white;border:1px solid #d5dce6;border-radius:9px;padding:4px 8px;font-size:12px}.attachment span{overflow-wrap:anywhere;min-width:0}.attachment img{width:44px;height:44px;object-fit:cover;border-radius:5px;flex-shrink:0}#prompt-state{font-size:12px;color:#995321;margin-top:10px}input[type=file]{display:none}
@media(max-width:700px){main{grid-template-columns:116px minmax(0,1fr);gap:12px;padding:8px 10px}.sidebar{padding-right:10px}.toolbar button{font-size:12px;padding:7px 8px}.bubble{max-width:96%;padding:10px 12px}header{align-items:flex-start;flex-direction:column;gap:0}h1{font-size:17px}#send{padding:0 10px}textarea{font-size:14px}.attachment{flex-direction:column;align-items:flex-start}.attachment img{width:40px;height:40px}}
</style></head><body><main>
<aside class="sidebar" aria-label="聊天功能"><h2>对话管理</h2>
<div class="toolbar"><button type="button" data-command="/help">帮助</button><button type="button" data-command="/chat status">上下文状态</button><button type="button" data-command="/chat compress">压缩</button><button type="button" data-command="/prompt upload">设置人设</button><button type="button" data-command="/prompt cancel">取消人设等待</button><button type="button" id="refresh">刷新历史</button><button type="button" id="stop-task">停止当前任务</button></div>
<div id="prompt-state" role="status"></div><h2>附件</h2><div class="toolbar"><button type="button" id="choose-image">添加图片</button><button type="button" id="choose-file">添加 txt/md</button><button type="button" id="clear-files">移除附件</button></div><input id="image-files" type="file" accept=".jpg,.jpeg,.png,.webp,.gif" multiple><input id="text-file" type="file" accept=".txt,.md"><div id="attachments"></div>
<details class="guide"><summary>使用说明</summary><p class="note">使用管理员 QQ <b>1574938194</b> 的同一份上下文。普通对话会保存；命令及命令回复不记入聊天历史。<br>明确任务可直接提出，或使用 <b>/task run</b>；提醒和后台任务通知仍发送到 QQ。支持图片识别、txt/md 文本附件与 <b>/voice say</b> 试听。<b>/prompt upload</b> 后单独上传 txt/md 文件，会将原文设为统一人设。</p></details></aside>
<section class="chat" aria-label="对话"><header><h1 id="title">QQ Bot · 对话调试</h1><span id="status">正在连接…</span></header>
<div id="messages" role="log" aria-live="polite"></div>
<form id="form"><textarea id="input" placeholder="输入消息，或 /help 查看命令。Enter 发送，Shift+Enter 换行。" aria-label="消息"></textarea><button id="send">发送</button></form>
<div id="progress" role="status">历史显示最近 50 轮；刷新页面后，临时命令结果不保留。</div>
</section></main><script nonce="__NONCE__">
const token='__TOKEN__', box=document.getElementById('messages'), input=document.getElementById('input'), progress=document.getElementById('progress');
let busy=false,name='机器人',selected=[],previewURLs=[];
function promptState(active){document.getElementById('prompt-state').textContent=active?'正在等待人设：5 分钟内下一条文本或 txt/md 原文将替换 system prompt。图片不会消耗等待。':''}
function clearFiles(){for(const url of previewURLs)URL.revokeObjectURL(url);previewURLs=[];selected=[];document.getElementById('attachments').replaceChildren();document.getElementById('image-files').value='';document.getElementById('text-file').value=''}
function choose(files,images){if(busy)return;const list=Array.from(files);if(!list.length)return;if(images&&(list.length>3||list.some(f=>f.size>5*1024*1024||!(/\.(jpg|jpeg|png|webp|gif)$/i.test(f.name))))){add('system','最多选择 3 张图片，每张不超过 5 MiB。');return}if(!images&&(list.length!==1||list[0].size>512*1024||!(/\.(txt|md)$/i.test(list[0].name)))){add('system','请选择一个 512 KiB 以内的 txt/md 文件。');return}clearFiles();selected=list;for(const file of list){const item=document.createElement('div');item.className='attachment';if(images){const img=document.createElement('img');img.alt='待发送图片';const url=URL.createObjectURL(file);previewURLs.push(url);img.src=url;item.append(img)}const label=document.createElement('span');label.textContent=file.name+' · '+Math.ceil(file.size/1024)+' KB';item.append(label);document.getElementById('attachments').append(item)}}
async function encodeFile(file){const bytes=new Uint8Array(await file.arrayBuffer());let binary='';for(let i=0;i<bytes.length;i+=32768)binary+=String.fromCharCode(...bytes.subarray(i,i+32768));return {name:file.name,data:btoa(binary)}}
function add(role,text,audio=[],images=[],files=[]){const row=document.createElement('div');row.className='row '+role;const label=document.createElement('div');label.className='label';label.textContent=role==='user'?'你':role==='system'?'提示':name;const bubble=document.createElement('div');bubble.className='bubble';bubble.textContent=text;row.append(label,bubble);for(const data of audio){const player=document.createElement('audio');player.controls=true;player.src='data:audio/wav;base64,'+data;bubble.append(player)}for(const data of images){const img=document.createElement('img');img.className='generated';img.alt='生成的图片';img.src='data:image/jpeg;base64,'+data;bubble.append(img)}for(const file of files){const link=document.createElement('a');link.textContent='下载 '+file.name;link.download=file.name;link.href='data:application/octet-stream;base64,'+file.data;bubble.append(document.createElement('br'),link)}box.append(row);box.scrollTop=box.scrollHeight}
async function api(path,options={}){const r=await fetch('/debug/'+path,{...options,headers:{'X-Debug-Token':token,'Content-Type':'application/json'}});let data;try{data=await r.json()}catch{throw Error('服务未返回有效响应，请检查 SSH 转发和机器人状态。')}if(!r.ok)throw Error(typeof data.detail==='string'?data.detail:'请求失败。');return data}
function pending(active){busy=active;for(const button of document.querySelectorAll('button'))button.disabled=active&&button.id!=='stop-task';input.disabled=active}
async function refresh(){try{const s=await api('state');name=s.name;document.getElementById('title').textContent=name+' · 对话调试';document.getElementById('status').textContent=s.model+' · QQ '+(s.qq_online?'在线':'离线（网页可聊天）');box.replaceChildren();for(const [u,a] of s.history){add('user',u);add('assistant',a)}if(!s.history.length)add('system','开始一段对话吧。也可以输入 /help 查看命令。');promptState(s.prompt_pending);if(s.prompt_pending)add('system','正在等待人设：5 分钟内下一条非命令文本会成为 system prompt。用 /prompt cancel 取消。')}catch(e){add('system',e.message)}}
async function send(text,withFiles=true){if(busy||(!text.trim()&&(!withFiles||!selected.length)))return;const files=withFiles?[...selected]:[];pending(true);add('user',text+(files.length?'\n[附件] '+files.map(f=>f.name).join('、'):''));if(withFiles)input.value='';const start=Date.now();progress.textContent='正在处理…';const timer=setInterval(()=>{progress.textContent='正在处理… '+Math.round((Date.now()-start)/1000)+' 秒，请勿重复提交。'},1000);try{const data=await api('chat',{method:'POST',body:JSON.stringify({text,files:await Promise.all(files.map(encodeFile))})});add('assistant',data.reply,data.audio,data.images,data.files);promptState(data.prompt_pending);if(withFiles)clearFiles();progress.textContent='已完成 · '+Math.round((Date.now()-start)/1000)+' 秒'}catch(e){add('system',e.message);progress.textContent='发送失败；连接中断时请先刷新历史，确认上一条是否完成。'}finally{clearInterval(timer);pending(false);input.focus()}}
document.getElementById('stop-task').addEventListener('click',async()=>{try{const data=await api('chat',{method:'POST',body:JSON.stringify({text:'/task stop'})});add('system',data.reply)}catch(e){add('system',e.message)}});document.getElementById('form').addEventListener('submit',e=>{e.preventDefault();send(input.value)});input.addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();send(input.value)}});for(const button of document.querySelectorAll('[data-command]'))button.addEventListener('click',()=>send(button.dataset.command,false));document.getElementById('refresh').addEventListener('click',async()=>{pending(true);try{await refresh()}finally{pending(false)}});document.getElementById('choose-image').addEventListener('click',()=>document.getElementById('image-files').click());document.getElementById('choose-file').addEventListener('click',()=>document.getElementById('text-file').click());document.getElementById('image-files').addEventListener('change',e=>choose(e.target.files,true));document.getElementById('text-file').addEventListener('change',e=>choose(e.target.files,false));document.getElementById('clear-files').addEventListener('click',clearFiles);window.addEventListener('beforeunload',()=>previewURLs.forEach(URL.revokeObjectURL));refresh();
</script></body></html>'''
